INSERT INTO `front_cms_home` (`id`, `title`, `subtitle`, `item_type`, `description`, `elements`, `active`) VALUES
(1, 'আমরা দ্রুত এবং নির্ভরযোগ্য', 'চিকিৎসা এবং স্বাস্থ্যসেবা প্রয়োজন', 'wellcome', 'আমারা সময়ের সাথে যুগউপযোগী সেবা প্রদান করে থাকি।বাংলাদেশের নাম্বার ওয়ান ডায়াগনস্টিক সেন্টার হল পপুলার ডায়াগনস্টিক সেন্টার।আমরা সর্বদা আপনাদের সেবা প্রদান করার লক্ষ্যে ব্রত থাকি।যেকোন সময় আমাদের সেবা গ্রহণ করার ক্ষেত্রে আমাদেরকে ফোন করুন।', '{\"image\":\"wellcome.png\"}', 0),
(2, 'আমাদের অভিজ্ঞ ডাক্তার দল', NULL, 'doctors', 'আমাদের সকল অভিজ্ঞ ডাক্তার  গন্দের তালিকা নিচে দেওয়া হল', '{\"doctor_start\":\"1\",\"image\":\"featured-parallax.jpg\"}', 0),
(3, 'আমাদের সেরা মেডিক্যাল সেবা', NULL, 'services', 'আমাদের কিছু সেরা মেডিক্যাল সেবা নিচে দেওয়া হল।', '', 0),
(4, 'অনলাইন ঝামেলা মুক্ত অ্যাপয়েন্টমেন্ট বুকিং', 'Medical Services', 'cta', '', '{\"mobile_no\":\"+\\u09ee\\u09ee\\u09e6\\u09e7\\u09ed\\u09ed\\u09eb\\u09ea\\u09eb\\u09ed\\u09e6\\u09e6\\u09ee\",\"button_text\":\"\\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u0985\\u09cd\\u09af\\u09be\\u09aa\\u09af\\u09bc\\u09c7\\u09a8\\u09cd\\u099f\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09ac\\u09c1\\u0995 \\u0995\\u09b0\\u09c1\\u09a8\",\"button_url\":\"appointment\",\"image\":\"appointment-booking-img.png\"}', 0),
(5, 'সেরা <span>ডিজিটাল</span> ল্যাব টেস্ট', NULL, 'slider', 'বাংলাদেশে এই প্রথম আমারাই ডিজিতাল পদ্ধতিতে বিভিন্ন ধরনের প্যাথলজি ল্যাব টেস্ট করে থাকি।এবং উহার রিপোর্ট অনলাইন অথবা অফলাইনে ডেলিভারি প্রদান করে থাকি।', '{\"position\":\"c-left\",\"button_text1\":\"\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09b8\\u09c7\\u09ac\\u09be \\u09b8\\u09ae\\u09c2\\u09b9\",\"button_url1\":\"#\",\"button_text2\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url2\":\"#\",\"image\":\"home-slider-1678826053.jpg\"}', 0),
(6, 'সেরা <span> মেডিক্যাল </span> প্রদানকারী', NULL, 'slider', 'বাংলাদেশে আমরাই প্রথম মেডিক্যাল সেবা প্রদান করার লক্ষে আধুনিক ডায়াগনস্টিক সেন্টার গড়ে তুলি।আমাদের এই প্রতিষ্ঠানে সকল ধরনের মেডিক্যাল সেবা প্রদান করি।', '{\"position\":\"c-center\",\"button_text1\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url1\":\"#\",\"button_text2\":\"\\u098f\\u0996\\u09a8\\u09bf \\u09b6\\u09c1\\u09b0\\u09c1 \\u0995\\u09b0\\u09c1\\u09a8\",\"button_url2\":\"#\",\"image\":\"home-slider-1678825928.jpg\"}', 0),
(7, 'আমাদের রয়েছে <span>দক্ষ</span> ডাক্তারদের দল', NULL, 'slider', 'আমাদের রয়েছে দক্ষ ডাক্তারদের দল।আমাদের সকল ডাক্তারগন উচ্চ শিক্ষিত, এবং তাদের রয়েছে বিভিন্ন স্বনামধন্য প্রতিষ্ঠানে প্র্যাকটিস করার অভিজ্ঞতা।', '{\"position\":\"c-right\",\"button_text1\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url1\":\"#\",\"button_text2\":\"\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09b8\\u09be\\u09a5\\u09c7 \\u09af\\u09cb\\u0997\\u09be\\u09af\\u09cb\\u0997 \\u0995\\u09b0\\u09c1\\u09a8\",\"button_url2\":\"contact\",\"image\":\"home-slider-1678826257.jpg\"}', 0),
(8, 'যোগ্য ডাক্তার', NULL, 'features', 'আমাদের রয়েছে দক্ষ ডাক্তারদের টিম। যারা সবসময় আপনাদের সেবা প্রদান করার লক্ষ্যে নিয়োজিত রয়েছেন।', '{\"button_text\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url\":\"#\",\"icon\":\"fas fa-user-md\"}', 0),
(9, 'নিয়মিত চেকআপ', NULL, 'features', 'আপনারা চাইলে যেকোন সময় আমাদের ডায়াগনস্টিক সেন্টার থেকে নিয়মিত চেক-আপ এর সুবিধা।', '{\"button_text\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url\":\"#\",\"icon\":\"fas fa-stethoscope\"}', 0),
(10, 'ল্যাব টেস্ট', NULL, 'features', 'আমাদের রয়েছে আধুনিক টেস্ট ল্যাব। এতে রয়েছে আধুনিক ডিজিটাল ল্যাব টেস্ট মেশিন সমূহ।', '{\"button_text\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url\":\"#\",\"icon\":\"fas fa-vial\"}', 0),
(11, '২৪ ঘণ্টা কাস্টমার সার্ভিস', NULL, 'features', 'আমাদের রয়েছে ২৪ ঘণ্টা কাস্টমার সার্ভিস।আমাদের বছরের ৩৬৫ টি খোলা।', '{\"button_text\":\"\\u09ac\\u09bf\\u09b8\\u09cd\\u09a4\\u09be\\u09b0\\u09bf\\u09a4 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\",\"button_url\":\"#\",\"icon\":\"far fa-clock\"}', 0),
(12, 'আমাদের সুখী রোগীদের মতামত', NULL, 'testimonial', 'আমাদের কিছু রোগীদের মতামত নিচে দেওয়া হল।', '', 0);
