INSERT INTO `front_cms_setting` (`id`, `application_title`, `captcha_status`, `recaptcha_site_key`, `recaptcha_secret_key`, `address`, `mobile_no`, `fax`, `receive_contact_email`, `email`, `footer_text`, `fav_icon`, `logo`, `working_hours`, `facebook_url`, `twitter_url`, `youtube_url`, `google_plus`, `linkedin_url`, `pinterest_url`, `instagram_url`) VALUES
(1, 'পপুলার ডায়াগনস্টিক সেন্টার', 'disable', '', '', 'হাউজঃ মুন্সি বাড়ি, নয়ার হাট হাই স্কুল সংলগ্ন, বড়বাড়ি, লালমনির হাট।', '+৮৮০১৭৭৫৪৫৭০০৮', '+৮৮০১৭৭৫৪৫৭০০৮', 'info@elitedesign.com.bd', 'info@elitedesign.com.bd', '© ২০২০ <span>পপুলার ডায়াগনস্টিক সেন্টার</span>, সকল কিছুর স্বত্বাধিকার', 'fav_icon.png', 'logo.png', '<span>সময়: </span>  শনি থেকে শুক্রবার - সকাল ৯:০০ থেকে ০৮:০০,  (২৪ ঘন্টা খোলা)', 'https://facebook.com/elitedesignbd', 'https://twitter.com/elitedesignbd', 'https://youtube.com/@/elitedesignbd', 'https://google.com', 'https://linkedin.com', 'https://pinterest.com', 'https://instagram.com');
INSERT INTO `front_cms_testimonial` (`id`, `patient_name`, `surname`, `image`, `description`, `rank`, `created_by`, `created_at`) VALUES
(1, 'মোঃ শামিম খান', 'বিজনেসম্যান', 'user-1678828763.png', 'আমি পপুলার ডায়াগনস্টিক সেন্টার এর প্যাথলজি টেস্ট নিয়ে খুব সন্তুষ্ট। তারা সবসময় সঠিক ও নিরভুল টেস্ট করে থাকে।', 1, 1, '2019-08-23 18:26:42'),
(2, 'জাহানারা খানম', 'গৃহিণী', 'user-1678827957.jpg', 'পপুলার ডায়াগনস্টিক এর সেবা পেয়ে খুব আনন্দিত।পপুলার ডায়াগনস্টিক সেন্টার খুব কম টাকায় ল্যাব টেস্ট করে থাকে।', 4, 1, '2019-08-23 18:26:42'),
(3, 'মোঃ নাইম হোসেন', 'স্টুডেন্ট', 'user-1678828077.png', 'পপুলার ডায়াগনস্টিক সেন্টার সবসময় কাস্টমারদের সঠিক সেবা প্রদান করার জন্য প্রস্তুত থাকে, ধন্যবাদ পপুলার ডায়াগনস্টিক সেন্টারকে।', 5, 1, '2019-08-23 18:26:42'),
(4, 'শাহিদা আক্তার', 'গৃহিণী', 'user-1678828211.png', 'আমার দেখা খুব ভালো একটি ডায়াগনস্টিক প্রতিষ্ঠান। এখানে আমি আমার MRI করেছি, তারা খুব নির্ভুল টেস্ট প্রদান করেছে।', 3, 1, '2019-08-23 18:26:42');
